// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value, bytes memory _data) public {
        vm.assume(_target != address(0) && _target != address(c));
        vm.assume(_value <= address(this).balance);
        vm.deal(address(c), _value);

        uint256 balanceBefore = address(c).balance;

        c.sendMoney(_target, _value, _data);

        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore - _value);
    }
}

