pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address _target, uint256 _value, bytes memory _data) public {
        vm.assume(_target != address(0) && _target != address(c));
        vm.assume(_value <= address(this).balance);
        vm.deal(address(c), _value);

        uint256 balanceBefore = address(c).balance;

